/* icons.h - icon and cursor tables (generated by tools/icongen.py) */
#ifndef RBUI_ICONS_H
#define RBUI_ICONS_H

#include "rbui_names.h"
#include <stdint.h>

typedef struct {
    const char *name;
    int size;              /* square: size x size */
    int hot_x, hot_y;      /* cursor hot spot */
    const uint32_t *pal;   /* AARRGGBB; index 0 is transparent */
    const uint8_t *px;     /* size*size palette indices */
    const uint32_t *argb;  /* or size*size AARRGGBB pixels (Platinum bundle icons, assets.c) */
} rbi_icon;

const rbi_icon *assets_icon(const char *name, int size);   /* assets.c; NULL if not loaded */

/* A Platinum control sprite from the bundle (chrome/<name>.rbi), drawn nine-slice with
 * the bundle manifest's slice widths (platinum.c, Mac OS 9.2.1 look). */
typedef struct {
    const char *name;
    int w, h;
    int slice[4];          /* top, right, bottom, left; 0 when the manifest has none */
    const uint32_t *argb;  /* w*h AARRGGBB */
} rb_sprite;

const rb_sprite *assets_sprite(const char *name);          /* assets.c; NULL if not loaded */
int assets_ramp(uint32_t ramp[8], uint32_t *highlight);    /* 1 when the bundle has its colours */
void assets_auto(void);
int assets_refresh(void);   /* reload a bundle hostd has rebuilt since; 1 when it did */
void assets_reset(void);  /* tests */   /* load the bundle once: $RBUI_ASSETS, else /var/lib/retroboot/assets/platinum */

extern const rbi_icon rbui_icons[];
extern const int rbui_icon_count;

#endif
